L7 = dict(n=7, name="اتوماسیون، API و داده", diff="adv", diff_label="پیشرفته", time="۹–۱۱ ساعت", goal="«می‌توانم کارها را خودکار کنم و با API و داده کار کنم.»",
 desc="این سطح پایتون را به دنیای بیرون وصل می‌کند: فایل‌ها به‌صورت انبوه، APIهای وب و یک دیتابیس واقعی.",
 prereq="سطح ۰۶ — generator، دکوریتور، context manager", final_short="دریافت، ذخیره و پرس‌وجوی داده", skills=["JSON/CSV", "HTTP/API", "SQLite", "subprocess"],
 concepts=[
 dict(id="c7-1", idx="7.1", title="سریالایز JSON", chip="JSON", ctx="تبدیل شیء پایتون و متن JSON",
  what="JSON قالب متنی برای داده‌ی ساخت‌یافته است. `json.dumps()` شیء را به رشته و `json.loads()` رشته را به شیء تبدیل می‌کند؛ `json.dump`/`json.load` همین را مستقیم روی فایل انجام می‌دهند.",
  mental="object ↔ dict، array ↔ list، string/number/boolean/null ↔ str/int-float/bool/None. تاپل هم به آرایه تبدیل می‌شود (تمایزش از بین می‌رود).",
  code=[("python", 'import json\n\ndata = {"name": "Ada", "skills": ["Python", "SQL"], "active": True}\ntext = json.dumps(data, indent=2)\nprint(text)\nprint(json.loads(text)["skills"][0])')], out='{\n  "name": "Ada",\n  "skills": [\n    "Python",\n    "SQL"\n  ],\n  "active": true\n}\nPython',
  mistake="`TypeError: Object of type datetime is not JSON serializable`؛ JSON نوع تاریخ ندارد.",
  fix="قبل از ذخیره با `my_date.isoformat()` به رشته تبدیل کن و هنگام بارگذاری با `datetime.fromisoformat()` برگردان.",
  ex=("code", "دیکشنری‌ای را در `config.json` ذخیره و دوباره بارگذاری کن.", 'import json\n\nconfig = {"debug": True, "retries": 3}\nwith open("config.json", "w") as f:\n    json.dump(config, f, indent=2)\nwith open("config.json") as f:\n    print(json.load(f)["retries"])'), exlabel="نوشتن کد"),
 dict(id="c7-2", idx="7.2", title="CSV: داده‌ی جدولی", chip="CSV", ctx="ماژول csv",
  what="ماژول `csv` داده‌ی جداشده با کاما را درست می‌خواند و می‌نویسد؛ از جمله وقتی کاما یا گیومه داخل یک فیلد باشد که `.split(\",\")` دستی اشتباه تحلیل می‌کند.",
  code=[("python", 'import csv\n\nrows = [{"name": "Ada", "score": 91}, {"name": "Bo", "score": 85}]\nwith open("scores.csv", "w", newline="") as f:\n    writer = csv.DictWriter(f, fieldnames=["name", "score"])\n    writer.writeheader()\n    writer.writerows(rows)\n\nwith open("scores.csv", newline="") as f:\n    for row in csv.DictReader(f):\n        print(row["name"], row["score"])')], out="Ada 91\nBo 85",
  mistake="تقسیم دستی خطوط روی `,`؛ وقتی فیلدی مثل `\"Smith, Jr.\"` کاما دارد می‌شکند.",
  fix="همیشه از `csv` استفاده کن. مقادیر خوانده‌شده همیشه رشته‌اند؛ برای عدد با `int()` تبدیل کن.",
  ex=("code", "`scores.csv` را بخوان و میانگین را چاپ کن.", 'import csv\nwith open("scores.csv", newline="") as f:\n    scores = [int(r["score"]) for r in csv.DictReader(f)]\nprint(sum(scores) / len(scores))'), exlabel="نوشتن کد"),
 dict(id="c7-3", idx="7.3", title="عبارت منظم با re", chip="عبارت منظم", ctx="تطبیق الگو در متن",
  what="عبارت منظم الگوهای متنی را توصیف می‌کند: `re.search()` (اولین تطبیق)، `re.findall()` (همه‌ی تطبیق‌ها)، `re.sub()` (جایگزینی).",
  code=[("python", 'import re\n\ntext = "Contact: ada@example.com or bo@work.org"\nprint(re.findall(r"[\\w.+-]+@[\\w-]+\\.[\\w.-]+", text))\nprint(re.sub(r"\\s+", " ", "too    many   spaces"))')], out="['ada@example.com', 'bo@work.org']\ntoo many spaces",
  mistake="استفاده از regex برای قالب‌هایی که پارسر مناسب دارند (JSON، HTML)؛ شکننده و خطاخیز است.",
  fix="برای JSON از `json`. regex را برای متن بدون ساختار یا الگوهای ساده نگه دار. الگوها را با رشته‌ی خام `r\"...\"` بنویس.",
  ex=("code", "همه‌ی اعداد را از `\"Order #42 shipped 3 items, 2 returned\"` استخراج کن.", 'import re\nprint(re.findall(r"\\d+", "Order #42 shipped 3 items, 2 returned"))'), exlabel="نوشتن کد"),
 dict(id="c7-4", idx="7.4", title="تاریخ و زمان", ctx="ماژول datetime",
  what="`datetime` یک نقطه‌ی مشخص از زمان است و `timedelta` یک بازه. `strftime` تاریخ را قالب‌بندی و `strptime` رشته را پارس می‌کند.",
  code=[("python", 'from datetime import datetime, timedelta\n\nnow = datetime(2026, 9, 16, 14, 30)\nprint(now.strftime("%Y-%m-%d %H:%M"))\nprint((now + timedelta(days=1)).strftime("%A, %B %d"))\nprint(datetime.strptime("2026-01-15", "%Y-%m-%d").year)')], out="2026-09-16 14:30\nThursday, September 17\n2026",
  mistake="ترکیب datetime «naive» (بدون منطقه‌ی زمانی) با «aware» در مقایسه؛ `TypeError` می‌دهد.",
  fix="یکدست باش: یا همه naive یا همه aware با `datetime.now(timezone.utc)`. لاگ‌ها و دیتابیس‌ها معمولاً UTC ذخیره می‌کنند.",
  ex=("code", "تاریخ ۳۰ روز بعد از امروز را چاپ کن.", 'from datetime import datetime, timedelta\nprint((datetime.now() + timedelta(days=30)).strftime("%Y-%m-%d"))'), exlabel="نوشتن کد"),
 dict(id="c7-5", idx="7.5", title="مبانی HTTP: درخواست، پاسخ، کد وضعیت", chip="مبانی HTTP", ctx="مدل بنیادین هر API وب",
  what="کلاینت یک **درخواست** (متد مثل `GET`/`POST`، URL، هدر و گاهی بدنه) می‌فرستد و سرور یک **پاسخ** (کد وضعیت، هدر، بدنه) برمی‌گرداند.",
  mental="`GET` داده می‌خواهد بدون اثر جانبی؛ `POST` معمولاً چیزی می‌سازد. کدها: `2xx` موفق، `3xx` تغییر مسیر، `4xx` خطای کلاینت (`404`)، `5xx` خطای سرور.",
  code=[("python", 'import requests\n\nresponse = requests.get("https://api.github.com/repos/python/cpython", timeout=5)\nprint(response.status_code)\ndata = response.json()\nprint(data["full_name"])')], out="200\npython/cpython", outlabel="خروجی (وابسته به پاسخ زنده‌ی سرور)",
  why="شبکه‌ها شکست می‌خورند. درخواست بدون `timeout` می‌تواند برنامه را بی‌نهایت متوقف کند؛ همیشه timeout بگذار و `requests.exceptions.RequestException` را مدیریت کن.",
  mistake="خواندن `response.json()` بدون چک وضعیت؛ پاسخ `404` یا `500` هم بدنه دارد ولی نه آن چیزی که انتظار داری.",
  fix="`response.raise_for_status()` را قبل از اعتماد به بدنه صدا بزن.",
  ex=("code", "تابع `fetch(url)` با timeout پنج‌ثانیه بنویس که JSON یا در صورت خطا `None` برگرداند.", 'import requests\n\ndef fetch(url):\n    try:\n        response = requests.get(url, timeout=5)\n        response.raise_for_status()\n        return response.json()\n    except requests.exceptions.RequestException as e:\n        print(f"Request failed: {e}")\n        return None'), exlabel="نوشتن کد"),
 dict(id="c7-6", idx="7.6", title="کار با APIهای JSON: احراز هویت، retry و خطا", chip="APIهای JSON", ctx="کلاینت API مقاوم",
  what="بیشتر APIهای واقعی احراز هویت می‌خواهند (کلید یا توکن در هدر) و ممکن است موقتاً شکست بخورند (محدودیت نرخ، قطعی کوتاه). کد حرفه‌ای هر دو را در نظر می‌گیرد.",
  code=[("python", 'import os, time, requests\n\ndef get_with_retries(url, headers, max_attempts=3):\n    for attempt in range(1, max_attempts + 1):\n        try:\n            r = requests.get(url, headers=headers, timeout=5)\n            if r.status_code == 200:\n                return r.json()\n            if r.status_code == 429:          # محدودیت نرخ\n                time.sleep(2 ** attempt)\n                continue\n            r.raise_for_status()\n        except requests.exceptions.RequestException as e:\n            print(f"Attempt {attempt} failed: {e}")\n    return None\n\napi_key = os.environ.get("API_KEY", "")\nheaders = {"Authorization": f"Bearer {api_key}"}')],
  why="خواندن راز از `os.environ` به‌جای نوشتن مستقیم در سورس، اعتبارنامه را از کنترل نسخه دور نگه می‌دارد. exponential backoff (`2 ** attempt`) الگوی استاندارد برای محدودیت نرخ است.",
  mistake="نوشتن کلید API مستقیم در اسکریپتی که commit می‌شود؛ به هر کسی که سورس یا تاریخچه‌ی Git را ببیند نشت می‌کند.",
  fix="رازها را از متغیر محیطی یا فایل `.env` محلیِ ignore‌شده بخوان.",
  ex=("text", "چرا retry فوری و بدون تأخیر بعد از هر شکست معمولاً ایده‌ی بدی است؟", "مشکل موقت را بدتر می‌کند؛ بمباران سروری که در حال دست‌وپنجه نرم‌کردن است می‌تواند قطعی را طولانی کند یا کلاینت را مسدود کند. backoff به سرور فرصت بازیابی می‌دهد."), exlabel="طراحی راه‌حل"),
 dict(id="c7-7", idx="7.7", title="مبانی SQLite: اتصال، cursor و SQL", chip="SQLite", ctx="دیتابیس رابطه‌ای داخلی پایتون",
  what="SQLite یک دیتابیس سبک و بدون سرور در یک فایل است که با `sqlite3` در کتابخانه‌ی استاندارد پایتون هست. **جدول** ردیف‌هایی با ستون‌های تعریف‌شده نگه می‌دارد و SQL زبان پرس‌وجوست.",
  code=[("python", 'import sqlite3\n\nconn = sqlite3.connect("app.db")\ncursor = conn.cursor()\ncursor.execute("""\n    CREATE TABLE IF NOT EXISTS users (\n        id INTEGER PRIMARY KEY,\n        name TEXT NOT NULL,\n        age INTEGER\n    )\n""")\ncursor.execute("INSERT INTO users (name, age) VALUES (\'Ada\', 36)")\nconn.commit()\n\ncursor.execute("SELECT name, age FROM users WHERE age > 18")\nfor row in cursor.fetchall():\n    print(row)\nconn.close()')], out="('Ada', 36)",
  steps=["`connect()` فایل دیتابیس را باز یا ایجاد می‌کند.", "cursor دستورهای SQL را اجرا می‌کند.", "`conn.commit()` تغییرات را ذخیره می‌کند؛ بدون آن ممکن است از دست بروند.", "`fetchall()` ردیف‌ها را به‌صورت لیست تاپل می‌دهد."],
  mistake="فراموش‌کردن `conn.commit()` بعد از `INSERT`/`UPDATE`/`DELETE`.",
  fix="بعد از هر نوشتن commit کن، یا از `with conn:` استفاده کن که خودکار commit/rollback می‌کند.",
  ex=("code", "پرس‌وجویی بنویس که تعداد کاربران بالای ۳۰ سال را بشمارد.", 'cursor.execute("SELECT COUNT(*) FROM users WHERE age > 30")\nprint(cursor.fetchone()[0])'), exlabel="نوشتن کد"),
 dict(id="c7-8", idx="7.8", title="کوئری پارامتری: جلوگیری از SQL injection", chip="کوئری پارامتری", ctx="چرا هرگز SQL را با چسباندن رشته نمی‌سازیم",
  what="کوئری پارامتری برای مقادیر جای‌نگهدار (`?` در `sqlite3`) می‌گذارد و مقدارها را جدا از متن SQL پاس می‌دهد.",
  why="اگر مقدار ورودی کاربر مستقیم داخل رشته‌ی SQL چسبانده شود، مهاجم می‌تواند ورودی‌ای بسازد که **ساختار** کوئری را عوض کند؛ این SQL injection است، از مخرب‌ترین آسیب‌پذیری‌های شناخته‌شده.",
  code=[("python — خطرناک، استفاده نکن", "username = user_input   # فرض کن: Ada' OR '1'='1\nquery = f\"SELECT * FROM users WHERE name = '{username}'\"\ncursor.execute(query)   # همه‌ی ردیف‌ها را برمی‌گرداند")],
  mistake="ساخت هر دستور SQL با f-string یا `+` که مقداری را شامل می‌شود که کاملاً زیر کنترل کد خودت نیست.",
  fix="همیشه مقدارها را به‌عنوان پارامتر بده:",
  fixcode='cursor.execute("SELECT * FROM users WHERE name = ?", (username,))',
  extra=[("استثنا ندارد", "ابزارهای داخلی و پنل‌های ادمین هم با همین اشتباه هک شده‌اند. هر مقدار را، هر بار، پارامتری کن.")],
  ex=("code", "این خط آسیب‌پذیر را امن بازنویسی کن: `cursor.execute(f\"DELETE FROM users WHERE id = {user_id}\")`", 'cursor.execute("DELETE FROM users WHERE id = ?", (user_id,))'), exlabel="اصلاح کد"),
 dict(id="c7-9", idx="7.9", title="subprocess: اجرای امن دستورهای خارجی", chip="subprocess", ctx="اجرای برنامه‌های دیگر و پرهیز از command injection",
  what="`subprocess.run()` برنامه‌ی دیگری را از پایتون اجرا می‌کند و می‌تواند خروجی‌اش را بگیرد.",
  code=[("python", 'import subprocess\n\nresult = subprocess.run(\n    ["ls", "-la"],          # لیست آرگومان، نه یک رشته‌ی شل\n    capture_output=True,\n    text=True,\n    timeout=10,\n)\nprint(result.returncode)\nprint(result.stdout[:100])')],
  why="`shell=True` همراه رشته‌ای ساخته‌شده از ورودی کاربر به مهاجم اجازه می‌دهد دستورهای اضافی را با `;` یا `&&` زنجیر کند و شل با کمال میل اجرا کند.",
  mistake="`subprocess.run(f\"ping {user_input}\", shell=True)`؛ اگر ورودی `\"example.com; rm -rf ~\"` باشد، شل هر دو را اجرا می‌کند.",
  fix="آرگومان‌ها را لیست بده و تا ممکن است `shell=True` نگذار: `subprocess.run([\"ping\", \"-c\", \"1\", user_input])`. همیشه `timeout` بگذار و `returncode` را چک کن.",
  ex=("code", "این را بدون `shell=True` بازنویسی کن: `subprocess.run(f\"cat {filename}\", shell=True)`", 'subprocess.run(["cat", filename])'), exlabel="اصلاح کد"),
 dict(id="c7-10", idx="7.10", title="الگوهای اتوماسیون: عملیات انبوه و متغیر محیطی", chip="الگوهای اتوماسیون", ctx="ترکیب فایل، subprocess و تنظیمات",
  what="اسکریپت‌های اتوماسیون معمولاً این‌ها را ترکیب می‌کنند: پیمایش فایل/رکورد زیاد (`pathlib`)، خواندن تنظیمات از محیط (`os.environ`) به‌جای هاردکد، و گزارش خلاصه در پایان.",
  code=[("python", 'import os\nfrom pathlib import Path\n\ntarget_dir = Path(os.environ.get("TARGET_DIR", "."))\nreport = {"renamed": 0}\n\nfor file in target_dir.glob("*.jpeg"):\n    file.rename(file.with_suffix(".jpg"))\n    report["renamed"] += 1\n\nprint(f"Renamed {report[\'renamed\']} files")')],
  mistake="اجرای عملیات مخرب انبوه (تغییر نام، حذف، بازنویسی) بدون آزمایش روی نمونه‌ی کوچک یا حالت «dry run».",
  fix="پرچم `dry_run` اضافه کن که کارهای قصدشده را به‌جای انجام چاپ کند و همیشه در پایان خلاصه بده (چند مورد پردازش، رد یا ناموفق شد).",
  ex=("text", "می‌خواهی لاگ‌های قدیمی‌تر از ۳۰ روز را حذف کنی. قبل از اجرای واقعی چه ایمنی‌ای اضافه می‌کنی؟", "حالت dry-run که دقیقاً فایل‌هایی که حذف می‌شوند (با تعداد و حجم کل) را بدون لمس‌کردن چیزی فهرست کند تا قبل از عمل برگشت‌ناپذیر بازبینی‌شان کنی."), exlabel="طراحی راه‌حل"),
 ],
 project=("پروژه‌های ۱۰ تا ۱۲ — تحلیلگر لاگ، جمع‌آور داده، اپ SQLite", "جزئیات: <a href=\"#project-10\">پروژه ۱۰</a>، <a href=\"#project-11\">۱۱</a> و <a href=\"#project-12\">۱۲</a>."),
 final=("اسکریپتی بساز که پاسخ JSON یک API عمومی را بگیرد، فیلدهای انتخابی را با کوئری پارامتری در SQLite ذخیره کند و خلاصه‌ای چاپ کند.", "fetch_and_store.py",
  'import sqlite3\nimport requests\n\nconn = sqlite3.connect("repos.db")\nconn.execute("CREATE TABLE IF NOT EXISTS repos (name TEXT, stars INTEGER)")\n\nresponse = requests.get(\n    "https://api.github.com/search/repositories",\n    params={"q": "language:python", "sort": "stars"},\n    timeout=5,\n)\nresponse.raise_for_status()\n\nwith conn:\n    for item in response.json()["items"][:5]:\n        conn.execute(\n            "INSERT INTO repos (name, stars) VALUES (?, ?)",\n            (item["full_name"], item["stargazers_count"]),\n        )\n\nfor row in conn.execute("SELECT name, stars FROM repos ORDER BY stars DESC"):\n    print(row)'))

L8 = dict(n=8, name="تست، مهندسی و کیفیت حرفه‌ای", diff="adv", diff_label="پیشرفته", time="۹–۱۱ ساعت", goal="«می‌توانم کد قابل‌تست و قابل‌نگهداری بنویسم.»",
 desc="این سطح فاصله‌ی «کدی که روی سیستم من کار می‌کند» با کدی است که یک تیم می‌تواند به آن اعتماد کند، گسترشش دهد و امن تغییرش دهد.",
 prereq="سطح ۰۷ — فایل، API، دیتابیس", final_short="مجموعه‌تست pytest با mock", skills=["pytest", "mocking", "logging", "ریفکتور", "امنیت"],
 concepts=[
 dict(id="c8-1", idx="8.1", title="چرا تست، و مبانی unittest", chip="unittest", ctx="تأیید خودکار به‌جای بررسی دستی",
  what="تست کدی است که کد دیگر را خودکار تأیید می‌کند. کتابخانه‌ی استاندارد پایتون `unittest` دارد (فریم‌ورک کلاس‌محور).",
  why="تست دستی کند است و زیر فشار ددلاین راحت نادیده گرفته می‌شود. تست خودکار **رگرسیون** را می‌گیرد: رفتاری که کار می‌کرد و تغییر بعدی بی‌خبر خرابش کرد.",
  code=[("calculator.py", "def add(a, b):\n    return a + b"), ("test_calculator.py", "import unittest\nfrom calculator import add\n\nclass TestAdd(unittest.TestCase):\n    def test_positive_numbers(self):\n        self.assertEqual(add(2, 3), 5)\n\n    def test_negative_numbers(self):\n        self.assertEqual(add(-1, -1), -2)\n\nif __name__ == \"__main__\":\n    unittest.main()")], out="..\nRan 2 tests in 0.001s\n\nOK",
  mistake="تست فقط «مسیر خوشحال» و هرگز ورودی خالی، صفر، منفی یا نادرست.",
  fix="عمداً برای مرزها و موارد خاص هم تست بنویس (۸.۴).",
  ex=("code", "متد تستی برای `add(0, 0) == 0` اضافه کن.", "def test_zero(self):\n    self.assertEqual(add(0, 0), 0)"), exlabel="نوشتن کد"),
 dict(id="c8-2", idx="8.2", title="pytest: fixture و assert ساده", chip="pytest", ctx="فریم‌ورک استاندارد تست",
  what="`pytest` (نصب با pip) اجازه می‌دهد تست را تابع ساده با `assert` بنویسی و **fixture** می‌دهد: کد راه‌اندازی قابل‌استفاده‌ی مجدد که به‌عنوان پارامتر تزریق می‌شود.",
  code=[("test_calculator.py", "import pytest\nfrom calculator import add\n\ndef test_positive_numbers():\n    assert add(2, 3) == 5\n\n@pytest.fixture\ndef sample_data():\n    return {\"a\": 2, \"b\": 3}\n\ndef test_with_fixture(sample_data):\n    assert add(sample_data[\"a\"], sample_data[\"b\"]) == 5")],
  why="fixture «آماده‌سازی موقعیت» را از «آنچه تست می‌سنجد» جدا می‌کند و چند تست می‌توانند یکی را به اشتراک بگذارند؛ با `yield` می‌شود پاک‌سازی هم داشت.",
  mistake="تست‌هایی که به ترتیب اجرا یا حالت مشترک از تست قبلی وابسته‌اند؛ گاهی موفق و گاهی ناموفق (flaky).",
  fix="هر تست باید همه‌چیز موردنیازش را با fixture بسازد و مستقل از ترتیب باشد. تست مسیر شکست: `with pytest.raises(ValueError):`.",
  ex=("code", "تستی بنویس که ثابت کند `int(\"abc\")` به `ValueError` می‌رسد.", 'import pytest\n\ndef test_invalid_int():\n    with pytest.raises(ValueError):\n        int("abc")'), exlabel="نوشتن کد"),
 dict(id="c8-3", idx="8.3", title="Mocking: تست بدون وابستگی واقعی", chip="Mocking", ctx="جایگزینی وابستگی کند یا خارجی",
  what="Mocking یک وابستگی واقعی (تماس شبکه، دیتابیس، زمان) را حین تست با جایگزین جعلی و کنترل‌شده عوض می‌کند تا تست سریع، قطعی و مستقل از سیستم‌های بیرونی باشد.",
  code=[("python", 'from unittest.mock import patch\n\n@patch("requests.get")\ndef test_with_patch(mock_get):\n    mock_get.return_value.json.return_value = {"temp": 22}\n    import requests\n    response = requests.get("http://example.com")\n    assert response.json()["temp"] == 22')],
  why="بدون mock، تست کدی که API واقعی صدا می‌زند کند، ناپایدار (با قطع شبکه می‌شکند) و شاید پرهزینه است.",
  mistake="mock کردن آن‌قدر زیاد که تست دیگر چیز معناداری از رفتار واقعی نمی‌سنجد.",
  fix="فقط مرز واقعی خارجی (خود تماس شبکه) را mock کن و کنارش تعداد کمتری تست یکپارچگی واقعی نگه دار.",
  ex=("text", "تابعی را تست می‌کنی که از سرویس شخص‌ثالث ایمیل می‌فرستد. چه چیزی را mock می‌کنی؟", "تماس شبکه‌ی واقعی به سرویس ایمیل؛ می‌خواهی تأیید کنی کد آن را درست و با آرگومان‌های درست صدا می‌زند، بی‌آنکه هر بار اجرای تست ایمیل واقعی بفرستد."), exlabel="طراحی راه‌حل"),
 dict(id="c8-4", idx="8.4", title="تست موارد خاص و رگرسیون", chip="موارد خاص و رگرسیون", ctx="آزمودن مرزها و قفل‌کردن باگ‌های رفع‌شده",
  what="مورد خاص ورودی‌ای در مرز یا فراتر از حالت معمول است: خالی، صفر، منفی، بسیار بزرگ، تکراری. تست رگرسیون را بعد از رفع باگ می‌نویسی تا همان باگ هرگز بی‌صدا برنگردد.",
  code=[("python", "def average(numbers):\n    if not numbers:\n        raise ValueError(\"cannot average an empty list\")\n    return sum(numbers) / len(numbers)\n\ndef test_average_empty_list_raises():\n    with pytest.raises(ValueError):\n        average([])\n\ndef test_average_negative_numbers():\n    assert average([-2, -4]) == -3")],
  why="بیشتر باگ‌های واقعی در مرزها زندگی می‌کنند نه وسط بازه‌ی «معمولی».",
  mistake="رفع باگ گزارش‌شده، تأیید دستی یک‌بار، و هرگز تست ننوشتن برای آن.",
  fix="هر رفع باگ باید تستی بیاورد که قبل از رفع شکست بخورد و بعد از آن موفق شود.",
  ex=("text", "سه مورد خاص برای تابعی که رشته‌ی اعداد با کاما را به لیست float تبدیل می‌کند نام ببر.", "رشته‌ی خالی؛ فاصله‌ی اضافه (`\"1, 2 ,3\"`)؛ مقدار غیرعددی که باید خطای واضح بدهد نه کرش مبهم."), exlabel="طراحی راه‌حل"),
 dict(id="c8-5", idx="8.5", title="Logging: فراتر از print", chip="Logging", ctx="خروجی تشخیصی سطح‌بندی‌شده",
  what="ماژول `logging` پیام‌های تشخیصی با زمان و سطح (`DEBUG`، `INFO`، `WARNING`، `ERROR`، `CRITICAL`) می‌سازد که می‌شود فیلتر کرد و به فایل فرستاد.",
  code=[("python", 'import logging\n\nlogging.basicConfig(level=logging.INFO, format="%(asctime)s %(levelname)s %(message)s")\nlogger = logging.getLogger(__name__)\n\ndef process_order(order_id):\n    logger.info(f"Processing order {order_id}")\n    try:\n        1 / 0\n    except ZeroDivisionError:\n        logger.error(f"Failed to process order {order_id}", exc_info=True)')],
  why="با `level=logging.INFO` پیام‌های `DEBUG` بدون حذف کد خاموش می‌مانند و می‌توانی موقتاً جزئیات را بالا ببری.",
  mistake="لاگ‌کردن داده‌ی حساس (رمز، شماره کارت کامل، کلید API) به‌صورت متن ساده در فایل لاگ.",
  fix="فیلدهای حساس را حذف یا ماسک کن: شناسه‌ی کاربر را لاگ کن، نه رمزش را.",
  ex=("code", "هنگام retry یک پیام هشدار با شماره‌ی تلاش لاگ کن.", 'logger.warning(f"Retry attempt {attempt} of {max_attempts}")'), exlabel="نوشتن کد"),
 dict(id="c8-6", idx="8.6", title="رفع‌اشکال سیستماتیک و pdb", chip="رفع‌اشکال و pdb", ctx="خواندن traceback و دیباگر داخلی",
  what="traceback زنجیره‌ی دقیق فراخوانی‌هایی را نشان می‌دهد که به خطا رسید: آخرین خط نوع و پیام خطا، و خط بالاتر محل دقیق. `pdb` اجازه می‌دهد اجرا را متوقف و متغیرهای زنده را بازرسی کنی.",
  steps=["**بازتولید** باگ را قابل‌اعتماد کن.", "**traceback** را از پایین به بالا بخوان.", "**جدا کن**: کدام متغیر یا ورودی خطا را تحریک می‌کند.", "**فرضیه** بساز و مستقیم تستش کن، نه حدس کورکورانه.", "**رفع و تأیید**: بازتولید اولیه را دوباره اجرا کن و تست رگرسیون اضافه کن."],
  code=[("python", "def calculate_discount(price, percent):\n    breakpoint()          # اجرا اینجا متوقف و pdb باز می‌شود\n    return price * (1 - percent / 100)\n\ncalculate_discount(100, 20)")], out="(Pdb) p price\n100\n(Pdb) n\n(Pdb) c", outlabel="نشست pdb",
  mistake="خواندن فقط آخرین خط یک traceback بلند و حدس‌زدن رفع، بدون بررسی کدام خط در **کد خودت** مسئول است.",
  fix="عمیق‌ترین فریمی که داخل فایل‌های پروژه‌ی خودت است را پیدا کن؛ رفع واقعی تقریباً همیشه آنجاست.",
  ex=("text", "برای `TypeError: unsupported operand type(s) for /: 'str' and 'int'` روی خط `percent / 100` بگو چه، کجا، چرا، رفع؟", "**چه:** `TypeError`. **کجا:** `percent / 100`. **چرا:** `percent` رشته است (مثلاً ورودی تبدیل‌نشده). **رفع:** `percent = float(percent)` در مرز تابع."), exlabel="تمرین رفع‌اشکال"),
 dict(id="c8-7", idx="8.7", title="PEP 8 و سازمان‌دهی کد", chip="PEP 8", ctx="راهنمای رسمی سبک پایتون",
  what="PEP 8 راهنمای رسمی سبک است: تورفتگی ۴ فاصله، `snake_case` برای تابع/متغیر، `PascalCase` برای کلاس، `UPPER_CASE` برای ثابت.",
  why="سبک یکدست یعنی توسعه‌دهنده انرژی ذهنی را روی منطق می‌گذارد نه روی تفسیر قالب‌بندی ناآشنا. فراتر از قالب‌بندی: هر تابع باید **یک کار** انجام دهد (انسجام و جداسازی مسئولیت).",
  code=[("terminal", "$ pip install black flake8\n$ black my_script.py     # قالب‌بندی خودکار\n$ flake8 my_script.py    # هشدار سبک و باگ‌های احتمالی")],
  mistake="تلاش برای به‌خاطر سپردن و اعمال دستی همه‌ی قوانین سبک در یک codebase بزرگ.",
  fix="از ابزارهای خودکار (`black` برای قالب‌بندی، `flake8` یا `ruff` برای lint) استفاده کن.",
  ex=("text", "PEP 8 برای کلاس `UserAccount` و تابع `get_user_account` چه قراردادی توصیه می‌کند؟", "کلاس‌ها `PascalCase` و توابع/متغیرها `snake_case`."), exlabel="یادآوری"),
 dict(id="c8-8", idx="8.8", title="Docstring و مستندسازی", ctx="مستندکردن کار کد برای انسان و ابزار",
  what="docstring رشته‌ی سه‌گیومه‌ای اولین دستور ماژول/تابع/کلاس است و با `.__doc__` و `help()` خوانده می‌شود.",
  code=[("python", 'def calculate_discount(price: float, percent: float) -> float:\n    """Return the price after applying a percentage discount.\n\n    Args:\n        price: The original price, must be non-negative.\n        percent: The discount percentage (0-100).\n\n    Raises:\n        ValueError: if percent is outside the 0-100 range.\n    """\n    if not 0 <= percent <= 100:\n        raise ValueError("percent must be between 0 and 100")\n    return price * (1 - percent / 100)')],
  why="docstring خوب قرارداد تابع را مستند می‌کند: چه می‌گیرد، چه تضمین می‌کند، چه چیزی می‌تواند خراب شود؛ فراخواننده لازم نیست پیاده‌سازی را بخواند.",
  mistake="docstring‌ای که فقط نام تابع را به جمله تبدیل می‌کند: `\"\"\"Calculates the discount.\"\"\"`.",
  fix="پارامترها، مقدار بازگشتی، استثناها و رفتار غیربدیهی را مستند کن.",
  ex=("code", "برای `is_prime(n: int) -> bool` docstring درست بنویس.", 'def is_prime(n: int) -> bool:\n    """Return True if n is a prime number, False otherwise.\n\n    Args:\n        n: An integer to test. Values less than 2 are never prime.\n    """\n    ...'), exlabel="نوشتن کد"),
 dict(id="c8-9", idx="8.9", title="ریفکتور و بوی بد کد", chip="ریفکتور", ctx="بهبود ساختار بدون تغییر رفتار",
  what="ریفکتور یعنی بازسازی ساختار کد برای خوانایی و نگهداری بیشتر **بدون تغییر رفتار بیرونی**؛ تست‌ها همان چیزی هستند که این کار را با اطمینان ممکن می‌کنند.",
  code=[("نسخه ۱ — کار می‌کند ولی شلوغ", 'def proc(d):\n    r = []\n    for i in d:\n        if i["status"] == "active" and i["balance"] > 0:\n            t = i["balance"] * 0.1 if i["type"] == "premium" else i["balance"] * 0.05\n            r.append({"name": i["name"], "fee": t})\n    return r'), ("نسخه ۲ — تمیزتر", 'PREMIUM_RATE = 0.10\nSTANDARD_RATE = 0.05\n\ndef is_billable(account):\n    return account["status"] == "active" and account["balance"] > 0\n\ndef calculate_fee(account):\n    rate = PREMIUM_RATE if account["type"] == "premium" else STANDARD_RATE\n    return account["balance"] * rate\n\ndef calculate_fees(accounts):\n    return [\n        {"name": a["name"], "fee": calculate_fee(a)}\n        for a in accounts\n        if is_billable(a)\n    ]')],
  why="در نسخه‌ی ۲ ثابت‌های نام‌دار جای اعداد جادویی را گرفته‌اند، هر تابع یک مسئولیت دارد و منطق مستقل قابل‌تست است (`is_billable` و `calculate_fee` جدا تست می‌شوند).",
  mistake="ریفکتور و افزودن ویژگی جدید در یک تغییر؛ اگر چیزی خراب شود نمی‌دانی کدام علت بوده.",
  fix="ریفکتور را جدا انجام بده، تست‌های موجود را قبل و بعد اجرا کن و بعد ویژگی جدید بیفزا.",
  ex=("text", "یک بهبود دیگر برای نسخه‌ی ۲ پیشنهاد بده.", "افزودن type hint و docstring به هر تابع؛ و استفاده از dataclass یا کلاس `Account` به‌جای دیکشنری خام با کلیدهای رشته‌ای که غلط تایپی‌پذیر و بی‌اعتبارسنجی‌اند."), exlabel="ریفکتور"),
 dict(id="c8-10", idx="8.10", title="پایتون امنیت‌محور: چک‌لیست عملی", chip="پایتون امنیت‌محور", ctx="جمع‌بندی عادت‌های امنیتی دوره",
  what="پایتون امنیت‌محور مهارتی جدا نیست؛ مجموعه‌ای از عادت‌هاست که روی همه‌ی آنچه یاد گرفتی اعمال می‌شود. این درس همه را در یک مرجع جمع می‌کند.",
  extra=[("چک‌لیست", "**اعتبارسنجی ورودی:** نوع، بازه و قالب را در مرز بسنج (سطح ۰۵). **SQL:** همیشه پارامتری (سطح ۰۷). **subprocess:** لیست آرگومان و بدون `shell=True` (سطح ۰۷). **path traversal:** مسیر نهایی را resolve کن و مطمئن شو داخل پوشه‌ی مجاز است. **رازها:** از متغیر محیطی یا secrets manager بخوان، هرگز هاردکد یا commit نکن. **deserialization:** هرگز `pickle.load()` روی داده‌ی نامطمئن؛ برخلاف `json` می‌تواند کد دلخواه اجرا کند. **وابستگی‌ها:** نسخه را در `requirements.txt` pin کن. **لاگ:** راز و داده‌ی حساس را لاگ نکن. **کمترین امتیاز:** اسکریپت فقط به دسترسی‌ای که لازم دارد دسترسی داشته باشد.")],
  code=[("python", 'from pathlib import Path\n\ndef safe_open(base_dir, user_filename):\n    base = Path(base_dir).resolve()\n    target = (base / user_filename).resolve()\n    if not target.is_relative_to(base):\n        raise ValueError("Invalid path: outside the allowed directory")\n    return open(target)')],
  mistake="فکر اینکه امنیت را می‌توان آخر پروژه اضافه کرد، یا اینکه «ابزار داخلی» به آن نیاز ندارد.",
  fix="این عادت‌ها را از خط اول اعمال کن؛ افزودن امنیت به یک codebase جاافتاده بسیار گران‌تر است.",
  ex=("text", "اسکریپتی نام فایل را از آرگومان خط‌فرمان می‌گیرد و می‌خواند. حداقل چه کاری قبل از اعتماد به آن لازم است؟", "مسیر کامل را resolve و تأیید کن که داخل پوشه‌ی پایه‌ی مجاز است (مثل `safe_open` بالا)."), exlabel="طراحی راه‌حل"),
 ],
 project=("پروژه‌های ۱۳ تا ۱۵ — مانیتور سیستم، ابزار شبکه‌ی async، پکیج تست‌محور", "جزئیات: <a href=\"#project-13\">پروژه ۱۳</a>، <a href=\"#project-14\">۱۴</a> و <a href=\"#project-15\">۱۵</a>."),
 final=("برای تابع `fetch(url)` سطح ۰۷ یک مجموعه‌تست pytest بنویس که `requests.get` را mock کند، مسیر موفق و شکست شبکه را بسنجد.", "test_fetch.py",
  'from unittest.mock import patch, MagicMock\nimport requests\nfrom client import fetch\n\n@patch("client.requests.get")\ndef test_fetch_success(mock_get):\n    resp = MagicMock()\n    resp.raise_for_status.return_value = None\n    resp.json.return_value = {"ok": True}\n    mock_get.return_value = resp\n    assert fetch("https://example.com") == {"ok": True}\n\n@patch("client.requests.get")\ndef test_fetch_network_failure_returns_none(mock_get):\n    mock_get.side_effect = requests.exceptions.ConnectionError("no network")\n    assert fetch("https://example.com") is None'))

L9 = dict(n=9, name="پایتون در دنیای واقعی و پروژه‌ی پایانی", diff="adv", diff_label="پیشرفته", time="۱۲–۱۵ ساعت", goal="«می‌توانم یک پروژه‌ی پایتونی جدی بسازم و مستند کنم.»",
 desc="سطح آخر همزمانی و معماری را پوشش می‌دهد و به پروژه‌ی پایانی می‌رسد؛ پروژه‌ای که می‌تواند نمونه‌کار واقعی تو شود.",
 prereq="سطح‌های ۰۱ تا ۰۸، به‌ترتیب", final_short="پروژه‌ی پایانی (بخش اختصاصی)", skills=["asyncio", "معماری", "پکیجینگ", "انتشار نرم‌افزار"],
 concepts=[
 dict(id="c9-1", idx="9.1", title="مدل‌های همزمانی: thread، process، asyncio", chip="مدل‌های همزمانی", ctx="سه ابزار و مسئله‌ای که هرکدام حل می‌کند",
  what="همزمانی یعنی ساختاردهی برنامه برای پیشرفت روی چند کار بدون اینکه هر کدام را کاملاً تمام کنی و بعد بروی سراغ بعدی. سه ابزار اصلی: **threading**، **multiprocessing** و **asyncio**.",
  why="GIL پایتون باعث می‌شود در هر لحظه فقط یک thread بایت‌کد پایتون اجرا کند. پس **threading کار CPU-محور را سریع نمی‌کند** ولی برای کار I/O-محور خوب است چون thread منتظر GIL را رها می‌کند. **multiprocessing** از process جدا (هرکدام مفسر و حافظه‌ی خودش) استفاده می‌کند و واقعاً روی چند هسته موازی اجرا می‌شود. **asyncio** با یک thread و event loop بین کارهای I/O-محور جابه‌جا می‌شود.",
  mental="آشپز (یک thread) را تصور کن: وقتی آب پاستا می‌جوشد (انتظار I/O) سبزی دیگری را خرد می‌کند. multiprocessing یعنی چند آشپز با آشپزخانه‌ی جدا که واقعاً هم‌زمان می‌پزند.",
  mistake="استفاده از `threading` برای تندکردن محاسبات سنگین و انتظار افزایش سرعت متناسب؛ GIL اجرای موازی واقعی کد پایتون بین threadها را مانع می‌شود.",
  fix="برای کار CPU-محور `multiprocessing`؛ برای کار I/O-محور (شبکه، دیسک، دیتابیس) `threading` یا `asyncio`.",
  ex=("text", "باید (الف) ۱۰٬۰۰۰ تصویر را ریسایز و (ب) ۱۰٬۰۰۰ URL را دانلود کنی. برای هرکدام چه ابزاری؟", "(الف) CPU-محور ← `multiprocessing`. (ب) I/O-محور ← `asyncio` یا `threading`."), exlabel="طراحی راه‌حل"),
 dict(id="c9-2", idx="9.2", title="مبانی async / await", ctx="کد هم‌کارانه و غیرمسدودکننده با asyncio",
  what="`async def` یک coroutine تعریف می‌کند. `await` (فقط داخل coroutine) آن را در نقطه‌ی انتظار I/O متوقف می‌کند و به event loop اجازه می‌دهد coroutine دیگری را اجرا کند.",
  code=[("python", 'import asyncio\n\nasync def fetch_page(name, delay):\n    print(f"Start fetching {name}")\n    await asyncio.sleep(delay)      # شبیه‌سازی انتظار شبکه\n    print(f"Finished fetching {name}")\n    return name\n\nasync def main():\n    results = await asyncio.gather(\n        fetch_page("A", 2),\n        fetch_page("B", 1),\n    )\n    print(results)\n\nasyncio.run(main())')], out="Start fetching A\nStart fetching B\nFinished fetching B\nFinished fetching A\n['A', 'B']",
  why="`await` دقیقاً نقاطی را نشان می‌دهد که coroutine حاضر به توقف است. event loop فقط در `await` صریح می‌تواند سراغ کار دیگری برود؛ استدلال درباره‌ی حالت مشترک بسیار ساده‌تر از threadهاست که ممکن است تقریباً در هر دستور عوض شوند.",
  extra=[("چرا B زودتر تمام می‌شود", "هر دو coroutine بلافاصله با `gather` شروع می‌شوند؛ `B` فقط ۱ ثانیه منتظر است پس زودتر تمام می‌شود، با اینکه `A` زودتر شروع شده.")],
  mistake="**مسدودکردن داخل کد async:** صدازدن تابع کند همزمان (مثل `time.sleep()` یا `requests`) داخل coroutine، که کل event loop و همه‌ی کارهای هم‌زمان را منجمد می‌کند.",
  fix="از معادل async استفاده کن: `asyncio.sleep()` به‌جای `time.sleep()` و یک کلاینت HTTP ناهمزمان به‌جای `requests`.",
  ex=("text", "اگر همین دو کار را ترتیبی با `time.sleep()` اجرا کنی، کل زمان نسبت به `gather` چقدر می‌شود؟", "ترتیبی: حدود ۳ ثانیه (۲+۱). با `gather`: حدود ۲ ثانیه؛ زمان کل تقریباً برابر طولانی‌ترین انتظار تکی است نه مجموع."), exlabel="پیش‌بینی خروجی"),
 dict(id="c9-3", idx="9.3", title="I/O-bound در برابر CPU-bound", ctx="تشخیص علت کندی قبل از انتخاب ابزار",
  what="کاری **I/O-bound** است که بیشتر زمانش منتظر چیزی بیرونی (شبکه، دیسک، فرآیند دیگر) باشد، و **CPU-bound** است که بیشتر زمانش واقعاً محاسبه روی CPU باشد. این تشخیص تعیین می‌کند کدام ابزار واقعاً کمک می‌کند.",
  why="همزمانی با thread یا asyncio روی مسئله‌ی CPU-محور فایده ندارد (انتظاری برای هم‌پوشانی نیست و GIL هم جلوی موازی‌شدن را می‌گیرد). multiprocessing برای مسئله‌ی سبک I/O-محور فقط پیچیدگی و سربار راه‌اندازی process می‌افزاید.",
  steps=["کار `requests` صدا می‌زند، دیتابیس می‌خواند یا فایل بزرگ می‌خواند؟ احتمالاً I/O-bound ← `asyncio`/`threading`.", "کار محاسبات سنگین یا پردازش تصویر/ویدیو بدون انتظار بیرونی دارد؟ احتمالاً CPU-bound ← `multiprocessing`.", "مطمئن نیستی؟ اول اندازه بگیر (profile)؛ گاهی راه‌حل واقعی الگوریتم بهتر است نه همزمانی."],
  mistake="رفتن سراغ همزمانی به‌عنوان اولین راه‌حل «اسکریپتم کند است» بدون اینکه بدانی زمان کجا می‌رود.",
  fix="اول اندازه‌گیری کن (حتی با `time.time()` دور بخش مشکوک)، بعد ابزار متناسب را انتخاب کن.",
  ex=("text", "اسکریپتی ۱۰۰ فایل را ترتیبی دانلود می‌کند و ۵ دقیقه طول می‌کشد؛ انتقال داده‌ی هر دانلود کمتر از ۱ ثانیه است و بقیه تأخیر شبکه. I/O-bound است یا CPU-bound؟", "I/O-bound؛ تقریباً همه‌ی زمان صرف انتظار شبکه است و اجرای هم‌زمان با asyncio یا thread زمان را به‌شدت کم می‌کند."), exlabel="یادآوری"),
 dict(id="c9-4", idx="9.4", title="معماری اپلیکیشن و ساختار پروژه", chip="معماری اپلیکیشن", ctx="سازمان‌دهی اپلیکیشن واقعی چندفایلی",
  what="فراتر از اسکریپت تکی، اپلیکیشن واقعی نگرانی‌ها را به ماژول‌های جدا تقسیم می‌کند: تنظیمات، منطق اصلی، دسترسی به داده، نقطه‌ی ورود؛ تا هر بخش جدا قابل‌فهم، تست و تغییر باشد.",
  code=[("ساختار پروژه", "myapp/\n├── pyproject.toml\n├── requirements.txt\n├── README.md\n├── .env.example\n├── myapp/\n│   ├── __init__.py\n│   ├── config.py        # تنظیمات و متغیرهای محیطی\n│   ├── models.py        # dataclassها\n│   ├── database.py      # SQLite و کوئری‌های پارامتری\n│   ├── services.py      # منطق اصلی\n│   ├── cli.py           # نقطه‌ی ورود\n│   └── logging_setup.py\n└── tests/\n    ├── test_services.py\n    └── test_database.py")],
  why="در مقایسه با یک اسکریپت ۸۰۰ خطی، `services.py` بدون دیتابیس واقعی (با mock کردن `database.py`) قابل‌تست است و `config.py` هر مقدار وابسته به محیط را در یک نقطه‌ی قابل‌بازبینی جمع می‌کند.",
  mistake="اجازه‌دادن به پروژه که در یک `main.py` همیشه‌بزرگ رشد کند تا هیچ‌کس (حتی نویسنده) نتواند پیش‌بینی کند تغییر یک تابع به چه چیزی ضربه می‌زند.",
  fix="به‌محض عبور از چند صد خط یا ترکیب نگرانی‌های مجزا (دسترسی به داده، منطق، CLI)، بر اساس مسئولیت تقسیم کن.",
  ex=("text", "تابع اعتبارسنجی ایمیل را کجا می‌گذاری؟", "در `validators.py` اختصاصی؛ منطق اعتبارسنجی قابل‌استفاده‌ی مجدد و قابل‌تست است و از شکل داده (`models.py`) و جریان کسب‌وکار (`services.py`) جداست."), exlabel="طراحی راه‌حل"),
 dict(id="c9-5", idx="9.5", title="پکیجینگ با pyproject.toml", ctx="تبدیل پوشه‌ی اسکریپت به پکیج نصب‌شدنی",
  what="`pyproject.toml` فایل پیکربندی استاندارد مدرن است که متادیتای پروژه (نام، نسخه، وابستگی‌ها) و نحوه‌ی ساخت آن را توصیف می‌کند؛ چیزی که پروژه را با `pip install .` نصب‌شدنی یا قابل انتشار روی PyPI می‌کند.",
  code=[("pyproject.toml", '[project]\nname = "myapp"\nversion = "0.1.0"\ndescription = "A small CLI tool for tracking expenses"\nrequires-python = ">=3.9"\ndependencies = [\n    "requests>=2.31",\n]\n\n[project.scripts]\nmyapp = "myapp.cli:main"')],
  why="بخش `[project.scripts]` یعنی بعد از نصب، تایپ `myapp` در ترمینال تابع `main` در `myapp/cli.py` را اجرا می‌کند؛ ابزارهای خط‌فرمان نصب‌شده با pip دقیقاً همین‌طور کار می‌کنند.",
  mistake="رهاکردن نسخه‌ی وابستگی‌ها بدون هیچ قیدی (`requests` تنها)؛ نصب آینده ممکن است تغییر ناسازگار را بی‌خبر بیاورد.",
  fix="حداقل یک نسخه‌ی سازگار را pin کن (`requests>=2.31`).",
  ex=("text", "کدام خط در `pyproject.toml` اجازه می‌دهد ابزار با تایپ نامش در ترمینال اجرا شود؟", "ورودی `[project.scripts]` مثل `myapp = \"myapp.cli:main\"`."), exlabel="یادآوری"),
 dict(id="c9-6", idx="9.6", title="جریان کار حرفه‌ای: از مسئله تا نرم‌افزار", chip="جریان کار حرفه‌ای", ctx="چطور مهارت‌های دوره در فرایند واقعی ترکیب می‌شوند",
  what="چرخه‌ای که توسعه‌دهنده‌های حرفه‌ای (تنها یا تیمی) به‌کار می‌برند: **مسئله ← برنامه‌ریزی ← پیاده‌سازی ← اجرا ← رفع‌اشکال ← تست ← ریفکتور ← مستندسازی ← انتشار**.",
  why="پریدن از «مسئله» به «پیاده‌سازی» بدون برنامه‌ریزی کدی می‌سازد که مسئله‌ی اشتباه را کارآمد حل می‌کند. نبودن «تست» و «ریفکتور» کدی می‌دهد که یک‌بار کار می‌کند ولی در برابر تغییر شکننده است. نبودن «مستندسازی» نرم‌افزاری می‌دهد که هیچ‌کس (از جمله خودت در آینده) نمی‌تواند با اطمینان نگهش دارد.",
  steps=["**کار می‌کند:** خروجی درست برای موردهایی که امتحان کردی.", "**قابل‌نگهداری:** ورودی بد را هم قابل‌پیش‌بینی مدیریت می‌کند، با خطای واضح می‌شکند نه پاسخ غلط بی‌صدا، تست دارد، سازمان‌یافته است و به‌قدر کافی مستند."],
  mistake="دیدن این مراحل به‌عنوان خط‌لوله‌ی یک‌طرفه؛ توسعه‌ی واقعی مدام برمی‌گردد (باگ هنگام تست تو را به پیاده‌سازی برمی‌گرداند).",
  fix="مراحل را چرخه‌ای ببین که هر کدام باید واقعاً رخ دهند قبل از اینکه کاری را «تمام‌شده» بدانی.",
  ex=("text", "اگر باگ گزارش‌شده‌ای را رفع می‌کنی (نه ویژگی جدید)، «افزودن تست» کجای جریان می‌نشیند؟", "اول تستی بنویس که باگ را بازتولید کند (شکست بخورد)، بعد رفع کن و ببین همان تست موفق شد؛ این هم اثبات رفع است و هم تست رگرسیون دائمی."), exlabel="طراحی راه‌حل"),
 ],
 project=("پروژه‌های ۱۶ و ۱۷ — ابزار اتوماسیون امنیت‌محور و اپلیکیشن حرفه‌ای نهایی", "جزئیات: <a href=\"#project-16\">پروژه ۱۶</a> و <a href=\"#project-17\">۱۷</a>."),
 final=("پروژه‌ی پایانی به‌طور کامل در بخش اختصاصی زیر مستند شده؛ مسئله، معماری، درخت فایل، برنامه‌ی پیاده‌سازی، برنامه‌ی تست و بازبینی امنیتی. <a href=\"#capstone\">رفتن به پروژه‌ی پایانی ←</a>",))
